impl Solution {
    pub fn count_monobit(n: i32) -> i32 {
        if n == 0 {
            return 1;
        }
        let mut count = 1;
        let mut current = 1;
        while current <= n {
            count += 1;
            current = (current << 1) | 1;
        }
        count
    }
}

